using Mbb.Archive.Modules.AccessControl.Application;
using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Configuration;using Microsoft.Extensions.DependencyInjection;using Mbb.Archive.BuildingBlocks.Application;using Mbb.Archive.Modules.AccessControl.Application.Abstractions;using Mbb.Archive.Modules.AccessControl.Application.Grants;using Mbb.Archive.Modules.AccessControl.Application.Roles;using Mbb.Archive.Modules.AccessControl.Infrastructure.Persistence;namespace Mbb.Archive.Modules.AccessControl.Infrastructure;public static class AccessControlModule{public static IServiceCollection AddAccessControlModule(this IServiceCollection s,IConfiguration c){var cs=c.GetConnectionString("AccessControl");if(string.IsNullOrWhiteSpace(cs))throw new InvalidOperationException("Connection string 'AccessControl' is not configured.");s.AddDbContext<AccessDbContext>(o=>o.UseNpgsql(cs));s.AddScoped<IAccessAdministration,EfAccessAdministration>();s.AddScoped<EfAccessRepository>();s.AddScoped<IAccessRepository>(sp=>sp.GetRequiredService<EfAccessRepository>());s.AddScoped<IPermissionChecker>(sp=>sp.GetRequiredService<EfAccessRepository>());s.AddScoped<IUnitOfWork<AccessControlBoundary>>(sp=>sp.GetRequiredService<AccessDbContext>());s.AddScoped<CreateRoleCommandHandler>();s.AddScoped<GrantPermissionCommandHandler>();s.AddScoped<AssignRoleCommandHandler>();s.AddScoped<EfAccessGrantRepository>();s.AddScoped<IAccessGrantRepository>(sp=>sp.GetRequiredService<EfAccessGrantRepository>());s.AddScoped<IAccessGrantQueries>(sp=>sp.GetRequiredService<EfAccessGrantRepository>());s.AddScoped<AccessGrantCommandHandlers>();s.AddScoped<AccessGrantQueryHandlers>();return s;}}
